// エリア別ページで使う、都県ごとの情報。
//
// 中身が同じページを都県の名前だけ変えて並べると、検索エンジンから
// 価値の無いページとみなされる。そうならないよう、ここには
// その土地でしか書けないこと（会場の例、地域の事情）を書く。
// 数字は毎回データベースから取るので、ここには書かない。

export type Area = {
  slug: string
  /** 画面に出す呼び方 */
  name: string
  /** places.prefecture に入っている値 */
  dbPref: string
  /** profiles.areas に入っている値 */
  sellerKey: string
  /** ページの導入。その土地の需要の特徴 */
  intro: string
  /** 実際に相談の多い会場の種類 */
  venues: string[]
  /** そのエリアならではの注意点 */
  notes: string[]
  /** 主な市区町村。検索語の受け皿にもなる */
  cities: string[]
}

